// Authored seven-column pre-effect SQLite layout; only bundled into private test artifacts.
import initSqlite from '@sqlite.org/sqlite-wasm';
import initWasm,{BrowserRuntime,inspect_package} from 'needware-wasm-runtime';
self.onmessage=async event=>{let db:any,stage="wasm";try{
  await initWasm({module_or_path:'/wasm/needware_wasm_bg.wasm'});stage="sqlite";const sqlite=await initSqlite();stage="opfs-root";const root=await navigator.storage.getDirectory();stage="opfs-file";const probe=await root.getFileHandle("legacy-access-probe",{create:true});stage="opfs-sync-handle";const access=await probe.createSyncAccessHandle();access.close();await root.removeEntry("legacy-access-probe");stage="pool";const pool=await sqlite.installOpfsSAHPoolVfs({directory:'/needware-opfs',initialCapacity:8});stage='database';db=new pool.OpfsSAHPoolDb('/library.sqlite');
  stage='schema';db.exec('PRAGMA journal_mode=DELETE; PRAGMA synchronous=FULL; CREATE TABLE apps(id TEXT PRIMARY KEY,title TEXT NOT NULL,digest TEXT NOT NULL,bytes BLOB NOT NULL,state TEXT NOT NULL,generation INTEGER NOT NULL,consent INTEGER NOT NULL);');
  db.exec('CREATE TABLE history(id TEXT NOT NULL,title TEXT NOT NULL,digest TEXT NOT NULL,bytes BLOB NOT NULL,state TEXT NOT NULL,generation INTEGER NOT NULL,consent INTEGER NOT NULL,PRIMARY KEY(id,generation));');
  stage='state';const bytes=new Uint8Array(event.data),info=JSON.parse(inspect_package(bytes)),runtime=new BrowserRuntime(bytes,undefined,true),source=JSON.parse(runtime.snapshot());source.values.name={type:'string',value:'Legacy private state'};runtime.restore(JSON.stringify(source));const state=runtime.snapshot();source.values.name={type:'string',value:'Legacy archived state'};
  stage='transaction';db.exec('BEGIN IMMEDIATE');try{db.exec({sql:'INSERT INTO apps VALUES(?,?,?,?,?,?,?)',bind:[info.application.id,info.application.title,info.digest,bytes,state,8,1]});db.exec({sql:'INSERT INTO history VALUES(?,?,?,?,?,?,?)',bind:[info.application.id,info.application.title,info.digest,bytes,JSON.stringify(source),7,1]});db.exec('COMMIT');}catch(error){db.exec('ROLLBACK');throw error;}runtime.free();db.close();db=undefined;
  stage='settings';await new Promise<void>((resolve,reject)=>{const request=indexedDB.open('needware-storage-choice-1',1);request.onupgradeneeded=()=>request.result.createObjectStore('settings');request.onerror=()=>reject(request.error);request.onsuccess=()=>{const store=request.result,tx=store.transaction('settings','readwrite');tx.objectStore('settings').put('opfs','backend');tx.oncomplete=()=>{store.close();resolve();};tx.onabort=()=>reject(tx.error);};});
  self.postMessage({ok:true,id:info.application.id});
}catch(error){db?.close();self.postMessage({ok:false,stage,error:stage+": "+String(error)});}};
